class JsonAuthenticationEntryPoint implements AuthenticationEntryPoint {
    @Override
    public void commence(HttpServletRequest request, HttpServletResponse response,
                          AuthenticationException authException) throws IOException {
        response.setStatus(401);
        response.setContentType("application/json");
        response.getWriter().write("""
            {"type":"about:blank","title":"Brak uwierzytelnienia","status":401}""");
    }
}

class JsonAccessDeniedHandler implements AccessDeniedHandler {
    @Override
    public void handle(HttpServletRequest request, HttpServletResponse response,
                        AccessDeniedException accessDeniedException) throws IOException {
        response.setStatus(403);
        response.setContentType("application/json");
        response.getWriter().write("""
            {"type":"about:blank","title":"Brak uprawnien","status":403}""");
    }
}

@Bean
SecurityFilterChain filterChain(HttpSecurity http) throws Exception {
    http.exceptionHandling(handling -> handling
            .authenticationEntryPoint(new JsonAuthenticationEntryPoint())
            .accessDeniedHandler(new JsonAccessDeniedHandler()));
    return http.build();
}

